def rows(s,n=2):
    return [tuple(p.strip() for p in raw.strip().split("|",n-1)) for raw in s.split(";") if raw.strip()]
def cfg(g,n,folder,title,pages,summary,topics,terms,people,events):
    return dict(grade=g,number=n,folder=folder,title=title,pages=pages,summary=summary,topics=rows(topics),terms=rows(terms),people=rows(people,3),events=events)
