    for i,x in enumerate(people,1): qs.append({"id":f"{p}-q-p{i:02d}","type":"short_answer","difficulty":"standard","topic":topics[(i-1)%len(topics)]["id"],"prompt":f"Welche historische Rolle spielte {x['name']}?","answer":x["relevance"]})
